const section = (title, paragraphs, checkpoint, extras = {}) => ({ title, paragraphs, checkpoint, ...extras })

const modules = [
  {
    id: 'support-foundations', number: '01', title: 'IT Support Foundations', time: '60–75 min',
    summary: 'Understand what an IT support specialist owns, how a business depends on IT, and how to work safely and professionally.',
    objectives: ['Explain the role of an IT support department', 'Use a repeatable support workflow', 'Communicate clearly with users and stakeholders'],
    sections: [
      section('What IT support actually does', ['IT support keeps people productive and business systems dependable. A specialist restores service when something breaks, prepares devices and accounts, teaches users, maintains records, and spots patterns before they become larger incidents. The job is not simply “fixing computers.” It connects people, devices, identities, applications, networks, servers, security, purchasing, and business priorities.', 'In this role you may be both a senior troubleshooter and an operational lead. You will handle difficult requests, help less-experienced technicians, coordinate with a supervisor, and turn repeated work into a documented process. Success means users can work, risks are controlled, records are accurate, and the team learns from each incident.'], { question: 'What is the difference between fixing a device and delivering IT support?', answer: 'A device fix is one technical action. IT support also protects the user’s work, communicates impact, documents the result, updates records, and prevents recurrence.' }, { terms: [['Service', 'A capability IT provides to the business.'], ['Stakeholder', 'A person or group affected by the work.'], ['Escalation', 'Moving an issue to someone with greater authority or expertise.']] }),
      section('The support lifecycle', ['A reliable workflow is: receive, acknowledge, assess, prioritize, diagnose, resolve or escalate, validate, document, and close. Skipping assessment can cause you to solve the wrong problem. Skipping validation can leave a user with a temporary workaround. Skipping documentation makes the next technician start over.', 'Start with open questions: What are you trying to do? What happens instead? When did it last work? Who else is affected? What changed? Then restate the issue in plain language and agree on the next update time.'], { question: 'Why should you restate the issue before troubleshooting?', answer: 'It confirms that you and the user agree on the symptom, desired result, scope, and impact before time is spent.' }, { steps: ['Acknowledge the request.', 'Clarify symptom, scope, timing, and impact.', 'Set priority and ownership.', 'Gather evidence and test safely.', 'Restore service or escalate.', 'Validate with the user and document.'] }),
      section('Safety, security, and authorization', ['Helpful intentions do not replace authorization. Before resetting a password, granting access, installing software, moving equipment, or changing a server, verify the requester and confirm the action is permitted. Use least privilege: give only the access needed, for only as long as needed.', 'Protect personal and company data. Do not ask a user to send a password. Lock unattended screens, use approved storage, follow disposal rules, and pause when a request could expose data or interrupt many people. A specialist is trusted because they know when not to make a change.'], { question: 'A manager asks you to read an employee’s mailbox. What should you do?', answer: 'Do not grant access from the request alone. Verify identity and follow the organization’s documented approval, privacy, and legal process.' }, { terms: [['Least privilege', 'The minimum access needed to perform approved work.'], ['Change control', 'A process for reviewing, approving, scheduling, and validating changes.']] }),
      section('Communication that reduces downtime', ['Users often describe effects rather than causes: “the internet is down” may mean one website, Wi-Fi, DNS, authentication, or the whole site. Avoid correcting them too early. Ask focused questions, explain what you are doing without jargon, and give realistic update times.', 'For leadership, report scope, business impact, current owner, evidence, workaround, risk, next action, and next update. For users, keep it simpler: what is affected, what they can do now, and when they will hear from you.'], { question: 'How would you update a user when you do not yet know the cause?', answer: 'State what is confirmed, the impact, any safe workaround, what you are checking next, and a specific time for the next update—without guessing.' }),
      section('Building your home practice lab', ['You can learn safely with two Windows virtual machines: one Windows Server evaluation VM and one Windows client VM on an isolated virtual network. The server can become a domain controller and the client can join the domain. Take snapshots before major changes and never connect an intentionally weak lab directly to a production network.', 'Keep a lab journal with the goal, starting state, commands, screenshots, result, and rollback. The habit of recording evidence matters as much as the technology.'], { question: 'Why take a virtual-machine snapshot before changing Active Directory or Group Policy?', answer: 'It gives the lab a known recovery point, allowing experimentation without rebuilding everything after a mistake.' }, { steps: ['Create an isolated virtual network.', 'Install a Windows Server VM.', 'Install a Windows client VM.', 'Record IP addresses and administrator credentials securely.', 'Snapshot both systems before major exercises.'] })
    ],
    command: 'Get-ComputerInfo | Select-Object CsName, WindowsProductName, WindowsVersion', commandNote: 'Start with read-only inventory: identify the machine and operating system before changing it.',
    interviewQuestions: [
      { question: 'How do you approach a support request from first contact to closure?', example: 'I acknowledge it, confirm the symptom, scope and business impact, assign priority, gather evidence, make the safest test, restore service, validate with the user, document the cause and actions, and identify follow-up work.' },
      { question: 'How do you explain technical problems to a nontechnical user?', example: 'I focus on what the user can observe and do, avoid unexplained acronyms, check understanding, and give a concrete next step and update time.' },
      { question: 'When would you refuse or pause a support request?', example: 'I pause when identity, authorization, data handling, security, or service impact is unclear. I explain the risk and use the approved escalation or change process.' }
    ]
  },
  {
    id: 'help-desk', number: '02', title: 'Help Desk Triage & Troubleshooting', time: '75–90 min', summary: 'Turn vague requests into well-prioritized, evidence-based resolutions.',
    objectives: ['Prioritize tickets by impact and urgency', 'Troubleshoot with hypotheses instead of guesses', 'Write tickets another technician can continue'],
    sections: [
      section('Impact, urgency, and priority', ['Impact describes how much of the business is affected; urgency describes how quickly harm grows. One executive unable to print may be urgent to that person but lower impact than an entire warehouse unable to ship. A payroll failure near a deadline may be both high impact and urgent.', 'Use the organization’s priority matrix and SLA. Do not prioritize only by job title or who complains loudest. Record the reason for the priority and re-evaluate it when scope changes.'], { question: 'Ten users cannot access a shared application, while one user has a broken mouse. Which normally comes first?', answer: 'The shared application issue because its business impact is broader, unless a documented safety or critical-business exception changes priority.' }, { terms: [['Impact', 'Breadth or severity of business effect.'], ['Urgency', 'How quickly the effect must be addressed.'], ['SLA', 'A service target such as response or resolution time.']] }),
      section('Ask questions that isolate the fault', ['Begin broad, then narrow. Determine whether the issue affects one person, one device, one location, one application, or everyone. Ask when it worked, what changed, whether an error appears, and whether another account or device behaves differently.', 'Each test should distinguish hypotheses. If the same user fails on two computers, identity or service becomes more likely. If two users work on the same computer but one does not, the user profile or permissions become more likely.'], { question: 'Why test another user on the same computer?', answer: 'It helps separate a machine-wide fault from an account, profile, or permission-specific fault.' }, { steps: ['Define expected versus actual behavior.', 'Determine scope.', 'Identify the last known good time and changes.', 'List likely layers.', 'Choose a low-risk differentiating test.', 'Record the observation.'] }),
      section('The layered troubleshooting model', ['Work from physical connection through device, network, operating system, identity, application, and remote service. For “email does not work,” confirm power and connectivity, test another site, check time and sign-in, inspect the mail application, then check service health.', 'Do not repeatedly change unrelated settings. Change one variable at a time and keep a rollback path. A workaround restores productivity; a resolution removes the cause. Label them correctly.'], { question: 'A browser reaches internal sites but not one cloud application. Which layer should you investigate next?', answer: 'The specific application, DNS path, identity, proxy, or cloud service—not basic device power or the entire LAN.' }),
      section('Ticket notes that create continuity', ['A good ticket records requester and device, expected and actual behavior, exact error, scope, impact, timestamps, evidence, tests and results, changes, approvals, workaround, final validation, and follow-up owner. “Fixed” is not useful.', 'Write chronological notes in neutral language. Separate facts from assumptions. Never store passwords, recovery codes, or unnecessary personal data in a ticket.'], { question: 'What is missing from the note “Reinstalled Office; fixed”?', answer: 'The symptom, scope, evidence, reason for reinstalling, approvals, version, result, user validation, cause, and prevention or follow-up.' }),
      section('Escalation and major incidents', ['Escalate when authority, expertise, access, time, vendor involvement, security risk, or business impact exceeds your boundary. A useful escalation is a prepared handoff, not a forwarded ticket. Include the timeline, evidence, steps already tried, current risk, and exact help needed.', 'During a widespread incident, avoid having many technicians make independent changes. Establish an incident owner, communication channel, timeline, action log, and update rhythm. Preserve evidence even while restoring service.'], { question: 'What should accompany an escalation?', answer: 'A concise problem statement, impact, timeline, evidence, completed tests with results, current state, risks, and a specific request for the receiving team.' })
    ], command: 'Get-WinEvent -LogName System -MaxEvents 20 | Format-Table TimeCreated, Id, LevelDisplayName, Message -Wrap', commandNote: 'Recent system events can provide evidence; an event is a clue, not automatically the root cause.',
    interviewQuestions: [
      { question: 'How do you prioritize several simultaneous tickets?', example: 'I use the approved impact-and-urgency matrix, consider safety and deadlines, communicate ownership and response targets, delegate where possible, and re-prioritize when scope changes.' },
      { question: 'Tell me how you would troubleshoot an issue you have never seen.', example: 'I define expected behavior, reproduce safely, map the layers involved, gather logs and changes, research authoritative documentation, test one hypothesis at a time, and escalate with complete evidence if needed.' },
      { question: 'What makes a help desk ticket high quality?', example: 'Someone unfamiliar with it can understand the impact, reproduce the symptom, see exactly what was tested, continue the work, and verify why it was closed.' }
    ]
  },
  {
    id: 'windows-clients', number: '03', title: 'Windows Workstations & User Profiles', time: '75–90 min', summary: 'Prepare, troubleshoot, secure, and retire Windows endpoints without losing user data.',
    objectives: ['Follow a repeatable workstation build', 'Diagnose Windows and profile issues', 'Validate upgrades and handoffs'],
    sections: [
      section('What happens when Windows starts', ['Firmware checks hardware, Windows Boot Manager loads the operating system, the kernel starts drivers, services start, and the sign-in system loads a user profile. Knowing the last successful stage narrows the problem.', 'A machine that never shows firmware differs from one at automatic repair, one that reaches sign-in, and one that fails only after a user signs in. Record the stage and exact message before restarting.'], { question: 'A second user can sign in successfully. What does that suggest?', answer: 'Core startup and machine-wide sign-in work, so the affected account, profile, permissions, or user-specific settings deserve attention.' }),
      section('A controlled workstation build', ['Start from an approved model and image. Record asset tag and serial, update supported firmware, install Windows, apply updates and drivers, configure encryption and security controls, enroll in management, install licensed applications, join the identity environment, and test hardware.', 'Do not copy an old user profile wholesale. Use approved migration tools and confirm what data is stored locally versus synchronized. The handoff should include user sign-in, network, printing, audio/video, required applications, updates, encryption escrow, and inventory.'], { question: 'What should be verified before handing a new workstation to a user?', answer: 'Identity, required apps, updates, security controls, encryption recovery, network, peripherals, user data, licensing, inventory, and the user’s core workflow.' }, { steps: ['Verify asset and hardware.', 'Install approved image and drivers.', 'Patch firmware and Windows.', 'Enroll security and management.', 'Install licensed applications.', 'Migrate approved data and validate with the user.'] }),
      section('Profiles, folders, and permissions', ['A Windows profile contains user-specific files and settings under C:\\Users. Domain identity and the local profile are related but not the same. A new profile can be created when the original is corrupt, unavailable, or mismatched.', 'Before profile repair, protect data and record sign-in identity. Check free space, profile service events, folder permissions, temporary-profile messages, synchronization status, and registry profile mapping. Avoid deleting the original profile until migration and validation are complete.'], { question: 'Why is deleting a corrupt profile immediately risky?', answer: 'It may contain the only local copy of user data and settings. Preserve and validate data before removal.' }, { terms: [['User profile', 'Per-user files and settings on a Windows device.'], ['SID', 'A security identifier Windows uses to identify a principal.'], ['NTFS permission', 'File-system access control on Windows volumes.']] }),
      section('Common endpoint diagnostics', ['Task Manager shows resource use and startup programs. Device Manager shows hardware and driver state. Event Viewer provides logs. Disk Management shows volumes. Reliability Monitor gives a timeline of failures. Windows Security, update history, system information, and vendor diagnostics add context.', 'High CPU is a symptom: identify the process and the trigger. Low disk space can break updates and profiles. A device warning may be driver, firmware, configuration, connection, or hardware—not proof that the device must be replaced.'], { question: 'A laptop is slow. What evidence would you gather before replacing it?', answer: 'Workload, CPU/memory/disk use, free space, temperatures, startup load, update state, event history, hardware health, age, and comparison with the required workload.' }),
      section('Upgrades, backup, and retirement', ['Before an operating-system or hardware upgrade, confirm compatibility, licensing, backups, free space, encryption recovery, application requirements, maintenance timing, rollback, and user communication. Pilot on a representative group before broad rollout.', 'Retirement requires data retention decisions, account and management removal, approved sanitization, inventory update, license recovery, and documented disposal. Merely deleting files does not reliably erase a drive.'], { question: 'Why pilot a Windows upgrade?', answer: 'A representative pilot exposes application, driver, policy, and workflow problems before they affect the whole organization.' })
    ], command: 'Get-CimInstance Win32_ComputerSystem; Get-BitLockerVolume; Get-Volume', commandNote: 'These read-only commands show identity, encryption, and storage state during build validation.',
    interviewQuestions: [
      { question: 'Walk me through setting up a workstation for a new employee.', example: 'I verify the request and asset, apply the approved build, patch it, enroll security and management, install licensed role-based apps, configure identity and peripherals, validate the user’s workflow, record inventory, and document handoff.' },
      { question: 'How would you troubleshoot a temporary Windows profile?', example: 'I preserve user data, confirm the account and free space, check User Profile Service events and profile mapping, inspect permissions and synchronization, then repair or create a clean profile under change control and validate migrated data.' },
      { question: 'How do you decide whether to repair or replace a computer?', example: 'I compare supported life, warranty, failure evidence, repair cost and time, security compatibility, user workload, recurrence, and business downtime—not just device age.' }
    ]
  },
  {
    id: 'm365-training', number: '04', title: 'Microsoft 365, Applications & User Training', time: '60–75 min', summary: 'Support productivity software and teach users in a way that reduces repeat tickets.',
    objectives: ['Separate app, identity, device, and service faults', 'Support common Microsoft 365 workflows', 'Design useful end-user training'],
    sections: [
      section('The layers behind Microsoft 365', ['A Microsoft 365 problem may involve the local application, license, user identity, multifactor authentication, device compliance, network, tenant configuration, or Microsoft service. First decide whether the web version works, whether another user is affected, and whether service health reports an incident.', 'Record the account used, application and version, device, error, time, scope, and recent changes. Be careful with cached credentials and token resets: they can sign a user out of several apps and should not be the automatic first step.'], { question: 'Outlook desktop fails but Outlook on the web works. What does that tell you?', answer: 'The mailbox, account, and broad network path probably work; focus on the desktop client, profile, cache, add-ins, local authentication, or device policy.' }),
      section('Word, Excel, PowerPoint, and files', ['Common problems include add-ins, protected view, blocked files, default apps, printer drivers, file corruption, permissions, macros, and version differences. Test a new blank file and the same file on another device or web app to isolate the document from the application.', 'OneDrive and SharePoint add synchronization, sharing, version history, retention, and conflict behavior. Confirm the authoritative file location before moving or deleting anything. A sync icon is evidence, not decoration.'], { question: 'One Excel workbook crashes, but new workbooks do not. What is your next direction?', answer: 'Investigate that workbook’s content, add-ins, links, macros, corruption, and compatibility rather than immediately reinstalling all of Office.' }),
      section('Email and collaboration troubleshooting', ['For mail flow, determine sender, recipient, direction, time, message trace availability, bounce text, size, spam or transport rules, and whether the issue is delay or rejection. For Teams, separate sign-in, meeting policy, network, camera/microphone permissions, driver, and selected-device problems.', 'Treat suspicious email as a security event. Preserve headers and use the approved reporting process; do not click links to “test” them or forward dangerous content casually.'], { question: 'What should you collect from a mail delivery failure?', answer: 'Sender, recipient, timestamp and timezone, subject or message ID, direction, bounce text, scope, and trace or filtering evidence.' }),
      section('Training adults effectively', ['Training should begin with a real task, not a tour of every menu. State the outcome, demonstrate it, let users practice, give a short job aid, check understanding, and provide a support path. Use plain language and accessible materials.', 'Measure whether training changes outcomes: completion, confidence, task success, related ticket volume, error rate, or time saved. If the same ticket repeats, improve the system or documentation instead of blaming users.'], { question: 'How would you teach employees a new sign-in process?', answer: 'I would explain why it matters, demonstrate the exact workflow, let users practice in a safe setting, cover common errors and recovery, provide an accessible quick guide, and measure successful adoption.' }, { steps: ['Define the audience and task.', 'Demonstrate one workflow.', 'Provide guided practice.', 'Check understanding with a realistic task.', 'Publish a concise job aid.', 'Measure adoption and revise.'] }),
      section('Supporting iPhone and iPad', ['For company iOS devices, distinguish personally owned from organization-owned devices and follow mobile device management and privacy policy. Common layers are device enrollment, Apple ID or managed identity, passcode, compliance, certificates, app deployment, mail profile, Wi-Fi, and cellular service.', 'Do not erase or remove management without confirming data ownership, backup, activation lock, authorization, and reassignment or retirement steps. Document model, serial, ownership, and management state in inventory.'], { question: 'What must you check before wiping an iPhone?', answer: 'Authorization, device ownership, backup and retention needs, management state, activation lock, identity removal, inventory, and the intended next use.' })
    ], command: 'Get-AppxPackage | Select-Object Name, Version | Sort-Object Name', commandNote: 'Application inventory helps confirm whether the expected Windows app package and version are present.',
    interviewQuestions: [
      { question: 'How would you troubleshoot a Microsoft 365 application issue?', example: 'I define scope, compare web and desktop behavior, check service health, identity and license, reproduce with another file or user, review app logs and updates, then make one reversible change and validate.' },
      { question: 'How do you handle a frustrated user who needs immediate help?', example: 'I acknowledge the impact, clarify the immediate business task, offer the safest workaround, explain the next action and update time, and remain accountable through validation.' },
      { question: 'How would you know an end-user training program worked?', example: 'I would set task-based outcomes and compare completion, proficiency, support volume, errors, and feedback before and after training, then revise weak areas.' }
    ]
  },
  {
    id: 'networking', number: '05', title: 'Networking for Support Specialists', time: '75–90 min', summary: 'Understand how devices reach local and internet services and isolate common network failures.',
    objectives: ['Explain IP, subnet, gateway, DNS, DHCP, Wi-Fi, and VPN', 'Use Windows network diagnostics', 'Escalate network issues with useful evidence'],
    sections: [
      section('How a device reaches a service', ['A network interface connects to Ethernet or Wi-Fi. An IP address identifies the device on a network, a subnet decides what is local, a default gateway forwards traffic elsewhere, and DNS translates names into addresses. A switch connects devices inside a LAN; a router connects networks; a firewall permits or blocks traffic by policy.', 'Think of reaching a website as a sequence: link, address configuration, local path, name resolution, route, firewall, remote service, then application protocol. Test from the bottom upward.'], { question: 'A user can reach a site by IP address but not by name. What is likely?', answer: 'The basic network path works, while DNS configuration, resolution, or the requested name is failing.' }, { terms: [['IP address', 'A network-layer address for an interface.'], ['Subnet', 'The local IP network boundary.'], ['Default gateway', 'The router used for nonlocal destinations.'], ['DNS', 'The system translating names to IP addresses.']] }),
      section('DHCP, addresses, and common symptoms', ['DHCP leases an address, subnet mask, gateway, DNS servers, and other options. A self-assigned 169.254.x.x address often means the client did not receive a DHCP lease. Duplicate addresses can cause intermittent reachability.', 'Use ipconfig /all to inspect configuration. Releasing or renewing a lease changes state; first record the original values. Compare a failing device with a healthy peer on the same network.'], { question: 'What does a 169.254 address usually indicate?', answer: 'Windows self-assigned a link-local address because normal DHCP configuration was unavailable.' }),
      section('Practical Windows network tools', ['ipconfig shows configuration; ping tests ICMP reachability when permitted; Test-NetConnection tests a destination and TCP port; nslookup or Resolve-DnsName checks DNS; tracert shows routed hops; arp shows local address mappings; and route print shows routing.', 'A failed ping does not prove a host is down because firewalls may block ICMP. Test the actual service port and application. Save exact destination, source, time, result, and comparison.'], { question: 'Why is Test-NetConnection server -Port 443 often more useful than ping?', answer: 'It tests the TCP port the application needs, while ping may be blocked or may succeed even when that service is unavailable.' }),
      section('Wi-Fi and VPN', ['Wi-Fi adds radio strength, interference, channel use, authentication, access points, roaming, and drivers. Ask whether the problem follows the device or location and compare signal and behavior with a healthy device.', 'VPN adds a client, tunnel authentication, MFA, routes, DNS, policy, certificates, and remote gateways. Determine whether the tunnel connects, which networks are routed through it, and whether the target works without VPN from an approved path.'], { question: 'A laptop works on Ethernet but not Wi-Fi. What fault domain narrows?', answer: 'The Wi-Fi adapter, driver, radio settings, wireless authentication, signal, access point, or wireless network policy.' }),
      section('Network escalation package', ['When escalating, include affected users and locations, wired or wireless, SSID or switch port if known, start time, IP configuration, gateway/DNS tests, target hostname and port, VPN status, recent changes, and a healthy comparison. Avoid vague claims such as “network slow.”', 'For performance, measure latency, loss, throughput, and time of day while separating application response from network response. Preserve security boundaries; do not run scans without authorization.'], { question: 'What makes a network escalation actionable?', answer: 'It identifies source, destination, protocol/port, scope, timestamps, configuration, test results, comparison, impact, and what changed.' })
    ], command: 'Get-NetIPConfiguration; Test-NetConnection example.com -Port 443; Resolve-DnsName example.com', commandNote: 'Together these inspect local configuration, a real service port, and name resolution.',
    interviewQuestions: [
      { question: 'A user says “the internet is down.” How do you troubleshoot?', example: 'I clarify scope, check link and IP configuration, test gateway, DNS and the actual destination port, compare another device and service, check VPN or proxy state, then escalate with source-to-destination evidence.' },
      { question: 'Explain DNS to a nontechnical interviewer.', example: 'DNS is the directory that turns a name people use, such as a website name, into the numerical network address computers use to connect.' },
      { question: 'What information do you give a network engineer?', example: 'Affected scope and location, source IP, destination and port, timestamps, wired/Wi-Fi/VPN context, configuration, reproducible tests, healthy comparison, changes, and business impact.' }
    ]
  },
  {
    id: 'windows-server', number: '06', title: 'Windows Server Fundamentals', time: '90 min', summary: 'Learn how Windows servers provide shared services and how to set them up and operate them safely.',
    objectives: ['Explain common Windows Server roles', 'Plan a basic server installation', 'Use logs, services, and monitoring for diagnosis'],
    sections: [
      section('What makes a server different', ['Windows Server is an operating system designed to provide services to many users or computers. Common roles include Active Directory Domain Services, DNS, DHCP, file and print services, web services, update or deployment services, and virtualization. A server may be physical or a virtual machine.', 'Before setup, define its business purpose, owner, data, users, dependencies, availability, backup, security, capacity, monitoring, licensing, network, recovery target, and support life. “Install Windows Server” is only a small part of delivering a service.'], { question: 'What should be defined before installing a new server?', answer: 'Purpose, ownership, dependencies, capacity, network and identity design, security, backup and recovery, monitoring, availability, licensing, support life, and acceptance tests.' }, { terms: [['Server role', 'A set of services providing a business capability.'], ['Virtual machine', 'A software-defined computer running on a host.'], ['Dependency', 'Another service or component required for operation.']] }),
      section('A safe server build', ['Use approved hardware or a supported virtualization platform. Configure management access, firmware, storage, networking, hostname, time, supported Windows edition, updates, drivers, activation, security baseline, monitoring, backups, and documented administration. Then install only required roles.', 'Use separate privileged accounts for administration and avoid browsing or email from servers. Record configuration in the organization’s system of record. Validate restore—not merely backup completion—before trusting recovery.'], { question: 'Why should an administrator avoid everyday web browsing on a server?', answer: 'It unnecessarily exposes a privileged, business-critical system to content and credentials risk.' }, { steps: ['Approve design and change.', 'Prepare hardware or VM and management.', 'Install and patch Windows.', 'Apply identity and security baseline.', 'Configure the required role.', 'Enable monitoring and backup.', 'Test service and recovery.'] }),
      section('Services, processes, and logs', ['A Windows service runs in the background, often before a user signs in. Services have identities, dependencies, startup types, and recovery behavior. A stopped service may be the symptom of a dependency, permission, configuration, resource, or application failure.', 'Use Server Manager, Services, Task Manager, Resource Monitor, Performance Monitor, Event Viewer, and PowerShell. Correlate System, Application, and role-specific logs by timestamp. Do not repeatedly restart a service before preserving evidence.'], { question: 'A service stops repeatedly. Why is setting it to restart forever incomplete?', answer: 'Restarting may restore service temporarily but hides the reason—such as a dependency, credential, resource, configuration, or application defect.' }),
      section('File shares and permissions', ['A file share uses both share permissions and NTFS permissions; the effective network access is the most restrictive combination. Assign access to groups rather than individual users when possible. Separate read, modify, and administrative needs.', 'Before changing permissions, identify the requested business role, data owner approval, inheritance, current group membership, and effect on existing access. Test with a representative nonadministrator account.'], { question: 'Why use groups for file access?', answer: 'Groups make access consistent, reviewable, scalable, and easier to remove when a person changes roles.' }),
      section('Maintenance, backup, and recovery', ['Patching requires inventory, relevance and known-issue review, backups, capacity, redundancy, maintenance approval, user communication, reboot expectations, validation, and rollback or recovery. Use rings: lab, pilot, then broader production deployment.', 'Define recovery time objective (how quickly service must return) and recovery point objective (how much data loss is acceptable). Test restorations and document who declares a disaster and who communicates.'], { question: 'What is the difference between RTO and RPO?', answer: 'RTO is the target time to restore service; RPO is the acceptable amount of data loss measured backward from the incident.' })
    ], command: 'Get-WindowsFeature | Where-Object InstallState -eq Installed; Get-Service | Where-Object Status -eq Stopped', commandNote: 'This inventories installed server roles and stopped services; stopped does not automatically mean broken.',
    interviewQuestions: [
      { question: 'Walk me through setting up a Windows server.', example: 'I begin with requirements and design, then approved compute, storage and network; install and patch; apply security, identity and management; configure only required roles; enable backup and monitoring; document; then test service, failure, and restore.' },
      { question: 'How do you troubleshoot a Windows service that will not start?', example: 'I capture the exact error and time, check service identity, dependencies, configuration, ports, resources and event logs, compare recent changes, test one hypothesis safely, then validate the dependent business service.' },
      { question: 'How do you reduce risk during server patching?', example: 'I use inventory and compatibility review, staged rings, tested backups, maintenance approval, communication, a recovery path, health checks, and post-patch service validation.' }
    ]
  },
  {
    id: 'active-directory', number: '07', title: 'Active Directory & Group Policy', time: '90 min', summary: 'Manage Windows identities, computers, access, and policy with clear scope and safe change practices.',
    objectives: ['Explain domains, objects, groups, and domain controllers', 'Handle common identity lifecycle work', 'Plan, diagnose, and validate Group Policy'],
    sections: [
      section('Active Directory in plain language', ['Active Directory Domain Services is a directory of users, computers, groups, and other objects. A domain controller authenticates identities and stores a replicated copy of directory data. DNS helps clients find domain services. Kerberos is the usual authentication protocol; LDAP is used to access directory information.', 'An organizational unit organizes objects and provides a scope for delegation and Group Policy. It is not automatically a security boundary. Multiple domain controllers improve availability, but replication and time must be healthy.'], { question: 'Why is DNS critical to Active Directory?', answer: 'Clients use DNS records to locate domain controllers and services. Incorrect DNS can look like sign-in, policy, or replication failure.' }, { terms: [['Domain controller', 'A server providing AD authentication and directory services.'], ['OU', 'A container used for organization, delegation, and policy scope.'], ['Kerberos', 'The primary ticket-based domain authentication protocol.'], ['Replication', 'Synchronization of directory changes between domain controllers.']] }),
      section('Users, computers, groups, and lifecycle', ['Use an approved request to create a user with the correct name, identifier, manager, department, groups, license, and expiration. Prefer role-based security groups over direct permissions. Disable and review access promptly during offboarding; retention and mailbox handling follow policy.', 'Computer accounts represent domain-joined devices. Stale accounts should be reviewed, not blindly deleted. Protect privileged groups, separate administrator identities, and regularly review access ownership.'], { question: 'Why is disabling usually safer than immediately deleting an offboarded account?', answer: 'It blocks sign-in while preserving identity references, audit history, ownership, and recovery options during the approved retention period.' }),
      section('Joining a computer and diagnosing sign-in', ['A client needs correct DNS, time, network reachability, a valid computer name, credentials with join permission, and communication with a domain controller. After joining, restart and validate computer placement, secure channel, user sign-in, policy, and management.', 'For sign-in failures, check exact error, scope, network, DNS, time, account state, lockout, password expiration, domain controller discovery, secure channel, and authentication logs. Do not reset a password before confirming identity.'], { question: 'Why can incorrect time prevent domain sign-in?', answer: 'Kerberos rejects authentication when clock difference exceeds the permitted tolerance because time protects against replay attacks.' }),
      section('How Group Policy applies', ['A Group Policy Object contains computer and user settings. Links apply GPOs to sites, domains, or OUs. Processing generally follows Local, Site, Domain, then OU, with later applicable settings able to win. Security filtering, WMI filters, inheritance, enforcement, loopback, permissions, and replication can change the result.', 'Design narrowly. Name GPOs by purpose, document owner and settings, avoid editing broad default policies for convenience, pilot in a test OU, back up the GPO, and have rollback. Group Policy refresh is not instant in every case; some settings require sign-out or restart.'], { question: 'A GPO is linked but not applying. What do you check?', answer: 'Object location, user versus computer scope, link state and order, inheritance, security and WMI filtering, permissions, replication, client connectivity, processing results, and whether restart or sign-out is required.' }),
      section('Tools and safe policy validation', ['Use Active Directory Users and Computers for objects, Group Policy Management for design and results, gpresult for client processing, gpupdate for refresh, Event Viewer for Group Policy and authentication logs, dcdiag for domain-controller health, and repadmin for replication.', 'Before changing policy, capture current resultant set, define expected affected objects, test on a representative pilot, verify both intended and unintended outcomes, and monitor support volume. Avoid running unfamiliar repair commands in production.'], { question: 'Why is gpresult valuable?', answer: 'It shows the policies and filters that actually applied to a specific user and computer, which may differ from what the administrator expected.' }, { steps: ['Define the desired behavior and scope.', 'Capture current policy result.', 'Create or change a narrowly scoped GPO.', 'Pilot with representative users and devices.', 'Verify security and business behavior.', 'Expand gradually and monitor.'] })
    ], command: 'gpresult /h "$env:TEMP\\gpresult.html"; Test-ComputerSecureChannel -Verbose', commandNote: 'The report explains applied policy; the secure-channel test checks the client’s domain trust without repairing it.',
    interviewQuestions: [
      { question: 'How would you troubleshoot a Group Policy that is not applying?', example: 'I confirm whether it is user or computer policy, inspect object OU and link scope, security/WMI filters and inheritance, use gpresult and policy logs, check connectivity and replication, then test a controlled refresh or restart.' },
      { question: 'How do you provision and deprovision users safely?', example: 'I require approved identity and role information, use role-based groups and least privilege, document licenses and assets, verify access with the owner, then disable promptly on exit and follow retention and access-review policy.' },
      { question: 'What is Active Directory?', example: 'It is Microsoft’s directory and authentication system for centrally managing identities, computers, groups, access, and policy in a Windows domain.' }
    ]
  },
  {
    id: 'powershell-deployment', number: '08', title: 'PowerShell & Enterprise Deployment', time: '90 min', summary: 'Automate repeatable support work and plan software rollouts that can be measured and reversed.',
    objectives: ['Read and write safe basic PowerShell', 'Design a staged software deployment', 'Collect reliable deployment evidence'],
    sections: [
      section('PowerShell’s object pipeline', ['PowerShell commands usually return objects with properties and methods, not unstructured text. Get-Process produces process objects; Where-Object filters them; Select-Object chooses properties; Sort-Object orders them; Export-Csv writes structured results.', 'Use Get-Help and Get-Command. Read commands usually begin with Get. Commands such as Set, New, Remove, Stop, Restart, and Invoke can change state. Understand scope and test with safe data before privileged execution.'], { question: 'How is the PowerShell pipeline different from a plain text pipeline?', answer: 'It passes structured objects with named properties, allowing reliable filtering and selection without parsing display text.' }, { terms: [['Cmdlet', 'A PowerShell command following Verb-Noun naming.'], ['Object', 'Structured data with properties and methods.'], ['Pipeline', 'Passes command output to the next command.']] }),
      section('Variables, conditions, loops, and errors', ['Variables begin with $. An if statement chooses a path, foreach repeats work, functions package reusable logic, and try/catch handles terminating errors. Use descriptive names, comments that explain why, and explicit parameters.', 'Scripts should validate inputs, log target and result, handle partial failure, avoid embedded secrets, support a dry run when possible, return meaningful exit codes, and be safe to run twice. Digital signing and execution policy may be part of organizational control.'], { question: 'What makes an administrative script safe to rerun?', answer: 'It checks current state and reaches the desired state without duplicating, corrupting, or reversing a correct configuration—an idea called idempotence.' }),
      section('Start with reporting automation', ['A safe first project is inventory or health reporting: collect computer name, OS, free disk space, encryption, last boot, or installed software. Test on one lab system, then a small device list. Handle offline and access-denied results separately.', 'Review data minimization and storage before collecting information. Include timestamp, script version, target, status, and error. A script that silently skips failures creates false confidence.'], { question: 'Why should an inventory script report failures as well as successes?', answer: 'Missing devices may represent the most important risk; explicit failures make coverage and data quality measurable.' }),
      section('Planning enterprise software deployment', ['Define business owner, package source and hash, license, supported systems, prerequisites, install and uninstall commands, silent switches, required restart, data impact, network capacity, detection rule, success criteria, support plan, and rollback.', 'Deploy through rings: lab, IT, representative pilot, then controlled production waves. Monitor installation success, application launch, business workflow, performance, security, and ticket volume. Stop when predefined thresholds are crossed.'], { question: 'What is a deployment detection rule?', answer: 'A reliable check—such as version, file, registry value, package ID, or product code—that confirms the intended software state.' }, { steps: ['Package and validate source.', 'Define prerequisites and detection.', 'Test install, upgrade, uninstall, and rollback.', 'Pilot with representative devices.', 'Deploy in measured waves.', 'Monitor technical and user outcomes.'] }),
      section('Upgrades, rollback, and reporting', ['An upgrade must consider existing versions, user data and settings, add-ins, file compatibility, running processes, disk space, reboot, and coexistence. A rollback must be tested before rollout, not invented during failure.', 'Report attempted, successful, failed, pending, and excluded devices with reasons. Use denominators: “95% success” means little without population, time window, and definition. Feed recurring failures into packaging and help desk knowledge.'], { question: 'When should an enterprise rollout be paused?', answer: 'When a predefined safety, failure-rate, business-impact, security, or support-capacity threshold is reached.' })
    ], command: 'Get-Service | Where-Object Status -eq Running | Select-Object -First 10 Name, DisplayName, StartType', commandNote: 'This demonstrates an object pipeline using read-only service data.',
    interviewQuestions: [
      { question: 'How would you deploy software to the enterprise?', example: 'I define requirements, package and detection, test install/upgrade/uninstall/rollback, communicate, pilot representative devices, deploy in waves with stop criteria, monitor outcomes, remediate failures, and document completion.' },
      { question: 'What would your first PowerShell automation be in a new environment?', example: 'A read-only inventory or health report. It produces value with low risk and lets me learn naming, access, data quality, and operational standards before automating changes.' },
      { question: 'How do you keep scripts from causing widespread damage?', example: 'I validate inputs and scope, use least privilege, dry-run and lab tests, small pilots, idempotent logic, explicit logging and errors, approvals, code review, version control, and a tested rollback.' }
    ]
  },
  {
    id: 'support-operations', number: '09', title: 'Support Operations, Assets & Leadership', time: '75–90 min', summary: 'Run organized support operations, track assets and purchasing, lead people through change, and handle after-hours work.',
    objectives: ['Maintain trustworthy asset and inventory records', 'Lead projects, training, and escalations', 'Use metrics and trends to improve service'],
    sections: [
      section('Asset lifecycle and inventory', ['An asset record should connect asset tag, serial, model, owner or custodian, location, status, purchase and warranty dates, cost center, configuration, management state, and disposal record. Inventory includes both deployed assets and stock.', 'Track receive, inspect, label, stock, assign, transfer, repair, return, and retire events. Perform periodic physical reconciliation. Decide which system is authoritative and restrict who can alter records.'], { question: 'Why record both an asset tag and manufacturer serial?', answer: 'The asset tag connects the item to internal ownership and finance; the serial supports exact hardware identity, warranty, and vendor service.' }, { terms: [['Asset', 'A tracked item with business value or risk.'], ['Custodian', 'The person responsible for an assigned asset.'], ['Reconciliation', 'Comparing records with physical reality and resolving differences.']] }),
      section('Purchasing and stock control', ['Purchase only with supervisor direction and approved vendors, standards, budgets, and licensing. Compare total lifecycle cost, not just price: compatibility, warranty, support, security updates, accessories, deployment labor, spares, and disposal matter.', 'Set minimum and maximum stock levels using consumption rate, lead time, failure history, criticality, and shelf life. Separate available, reserved, defective, and return-pending inventory. Prevent shadow purchasing from creating unsupported devices.'], { question: 'How would you decide how many spare laptops to keep?', answer: 'Use workforce and replacement demand, repair/failure rate, vendor lead time, onboarding forecast, device standardization, business criticality, storage capacity, and budget.' }),
      section('Spotting and reporting growing issues', ['Tag tickets consistently by service, symptom, cause, location, and device model. Look for increases in volume, repeat contacts, reopened tickets, common errors, failed deployments, aging assets, and shared time or location. Normalize counts when populations differ.', 'A useful problem report states pattern, affected population, business risk, supporting data, likely hypotheses, immediate containment, options with cost and risk, and a recommended next step. Distinguish correlation from proven cause.'], { question: 'How would you report a rise in Wi-Fi tickets?', answer: 'I would quantify rate and affected locations/times/devices, validate ticket classification, compare network evidence and changes, state hypotheses and business impact, propose containment and tests, and assign owners and review dates.' }),
      section('Planning projects and managing priorities', ['Turn a project into outcome, scope, exclusions, stakeholders, dependencies, risks, milestones, owners, communication, validation, rollback, support handoff, and closure criteria. Keep a decision and risk log.', 'For daily work, reserve capacity for incidents, rank work by impact and deadline, make ownership visible, delegate with context and acceptance criteria, and renegotiate scope when new urgent work arrives. Independent work still requires transparent status and escalation.'], { question: 'How do you work independently without surprising your supervisor?', answer: 'I align on outcomes and authority, make priorities and risks visible, provide concise scheduled updates, document decisions, and escalate early when scope, impact, cost, or approval changes.' }),
      section('After-hours support and team leadership', ['An on-call handoff should include open incidents, fragile systems, planned changes, contacts, access readiness, escalation thresholds, and communication expectations. During after-hours work, follow the same approval and evidence standards; fatigue increases risk.', 'Lead L1 technicians with decision trees, examples, shadowing, review, and constructive feedback. Blameless review asks how systems and processes allowed an error and what guardrails will help. Recognition, clarity, and psychological safety improve escalation quality.'], { question: 'What should an on-call handoff contain?', answer: 'Known incidents and risks, planned changes, current system state, owners and contacts, access, runbooks, escalation thresholds, and expected update channels.' }),
      section('Metrics that improve service', ['Useful measures include first response, time to restore, backlog age, first-contact resolution, reopen rate, SLA attainment, customer feedback, asset accuracy, deployment success, and recurring-issue rate. Each needs a clear definition and time window.', 'Metrics should prompt learning, not gaming. A fast close with repeated reopenings is poor service. Pair speed with quality, business impact, security, and user outcome. Review trends, choose one improvement, assign an owner, and measure again.'], { question: 'Why can ticket closure count be a harmful standalone metric?', answer: 'It rewards easy or premature closure and ignores complexity, quality, recurrence, business impact, teamwork, and user outcome.' })
    ], command: 'Get-Date; Get-CimInstance Win32_BIOS | Select-Object SerialNumber; Get-CimInstance Win32_ComputerSystem | Select-Object Manufacturer, Model', commandNote: 'A timestamped identity check supports inventory reconciliation and service records.',
    interviewQuestions: [
      { question: 'How would you organize and oversee a busy support department?', example: 'I establish priority rules, ownership, queues and escalation paths; maintain runbooks and an asset system; track balanced service metrics; coach the team; communicate risks; and use recurring-ticket analysis to improve the environment.' },
      { question: 'Tell me how you manage competing priorities.', example: 'I compare impact, urgency, deadlines, dependencies and risk, make the queue visible, delegate with clear outcomes, communicate tradeoffs, and revisit priorities as new evidence arrives.' },
      { question: 'How do you prepare for after-hours support?', example: 'I confirm access and contacts, review open incidents and planned changes, understand escalation thresholds, keep runbooks current, communicate handoffs, and avoid risky unapproved changes under fatigue.' }
    ]
  }
]

const quizQuestions = [
  { question: 'Which ticket should normally receive the highest priority?', options: ['One user wants a cosmetic desktop change', 'The warehouse shipping system is unavailable for all users', 'A spare monitor has a scratch', 'A manager asks for a future software quote'], answer: 1, explanation: 'A business-critical service outage affecting many users has the greatest impact and urgency.' },
  { question: 'A problem follows one user across two healthy computers. Where should you focus?', options: ['Building power', 'The monitor cable', 'The user identity, permissions, or cloud profile', 'Both computers’ motherboards'], answer: 2, explanation: 'Following the user points toward identity or user-specific state rather than one device.' },
  { question: 'A Windows client receives 169.254.22.8. What likely failed?', options: ['DHCP configuration', 'The CPU fan', 'Microsoft Word licensing', 'The display driver'], answer: 0, explanation: 'Windows commonly self-assigns a 169.254 address when it cannot obtain a DHCP lease.' },
  { question: 'Which practice best protects access management?', options: ['Give permissions directly to everyone', 'Share one administrator account', 'Use role-based groups and least privilege', 'Keep departed accounts active'], answer: 2, explanation: 'Role-based groups and least privilege make access controlled and reviewable.' },
  { question: 'What should you use to see which Group Policies actually applied?', options: ['ping', 'gpresult', 'format', 'notepad'], answer: 1, explanation: 'gpresult reports resultant Group Policy for a user and computer.' },
  { question: 'What is the safest first PowerShell automation?', options: ['Delete stale accounts', 'Restart every server', 'A read-only inventory report', 'Disable the firewall'], answer: 2, explanation: 'Read-only reporting provides value while limiting risk and revealing environment standards.' },
  { question: 'Before wiping a returned phone, what is essential?', options: ['Change its wallpaper', 'Confirm authorization, data policy, backup, ownership, and activation lock', 'Remove its asset tag', 'Guess whether data was synchronized'], answer: 1, explanation: 'Mobile retirement must protect company/user data and avoid activation-lock or custody problems.' },
  { question: 'A deployment reports 95% success. What else is needed?', options: ['Nothing', 'Population, time window, success definition, and failed-device reasons', 'Only the package name', 'A screenshot from one computer'], answer: 1, explanation: 'A percentage is meaningful only with a denominator, definition, period, and failure detail.' },
  { question: 'What is the best way to validate end-user training?', options: ['Count the slides', 'Ask whether the trainer enjoyed it', 'Measure realistic task success and related support outcomes', 'Make the class longer'], answer: 2, explanation: 'Training should improve user capability and measurable work outcomes.' },
  { question: 'A service restarts but fails again every hour. What should you do?', options: ['Schedule endless restarts', 'Preserve logs and investigate dependencies, identity, resources, configuration, and changes', 'Delete all event logs', 'Replace every workstation'], answer: 1, explanation: 'Repeated restart is a workaround; evidence is needed to find the underlying mechanism.' },
  { question: 'What makes an escalation useful?', options: ['Forwarding the ticket with “please help”', 'A complete evidence-based handoff with a specific request', 'Removing prior notes', 'Waiting until the SLA expires'], answer: 1, explanation: 'The receiving team needs impact, scope, timeline, evidence, tests, state, risk, and the help requested.' },
  { question: 'Which is a balanced help desk quality measure?', options: ['Closure count alone', 'Fastest technician only', 'Time to restore together with reopen rate and user outcome', 'Number of password resets'], answer: 2, explanation: 'Speed must be paired with durable resolution and user/business outcomes.' }
]

const glossary = [
  ['Active Directory', 'Microsoft directory services for identities, computers, groups, and policy.'], ['DHCP', 'Automatically supplies network configuration to clients.'], ['DNS', 'Translates service names into IP addresses.'], ['Domain controller', 'A server that authenticates domain identities and stores directory data.'], ['GPO', 'A Group Policy Object containing centrally managed Windows settings.'], ['IP address', 'A network address assigned to an interface.'], ['Kerberos', 'The primary ticket-based authentication protocol in an AD domain.'], ['Least privilege', 'Only the minimum approved access needed.'], ['MFA', 'Authentication using more than one type of proof.'], ['MDM', 'Central management of mobile devices and their policies.'], ['NTFS', 'The Windows file system with file and folder access controls.'], ['OU', 'An Active Directory container used for organization, delegation, and policy scope.'], ['PowerShell', 'Microsoft command shell and automation language built around objects.'], ['RPO', 'The maximum acceptable amount of data loss measured in time.'], ['RTO', 'The target time to restore a service.'], ['SLA', 'A measurable service commitment or target.'], ['SID', 'A Windows security identifier for a user, group, or computer.'], ['Ticket', 'The tracked record of a request, incident, or work item.'], ['VPN', 'An encrypted connection into a private network.'], ['Windows service', 'A background process managed by the Service Control Manager.'], ['Asset tag', 'An organization-assigned identifier for tracked equipment.'], ['Change control', 'Review, approval, scheduling, execution, and validation of a change.'], ['Incident', 'An interruption or reduction in the quality of a service.'], ['Root cause', 'The underlying mechanism that produced a problem.'], ['Workaround', 'A temporary method that reduces impact without removing the cause.']
]

const scenarios = [
  { title: 'Monday morning sign-in failures', prompt: 'Eight users in one office cannot sign in to the domain after a weekend network change.', clues: ['Local cached sign-in works for some users.', 'Clients show the correct IP range but an unexpected DNS server.', 'The domain controller is healthy from another site.'], answer: 'Treat this as a scoped incident. Preserve client configuration, compare with a healthy site, test DNS and domain-controller discovery, and coordinate correction of DHCP/DNS settings. Validate new leases, authentication, Group Policy, and business applications.' },
  { title: 'Enterprise application rollout', prompt: 'A required application must be upgraded on 450 Windows devices before month-end.', clues: ['Two departments use a legacy add-in.', 'The installer requires a restart.', 'Forty laptops are often off-network.'], answer: 'Inventory versions and dependencies, package install/uninstall/detection, test the add-in and rollback, communicate restart expectations, pilot representative departments, deploy in waves with stop criteria, handle remote devices separately, and report success and failures against all 450.' },
  { title: 'Recurring laptop failures', prompt: 'Tickets for unexpected shutdowns are rising on one laptop model.', clues: ['Most devices are 30–36 months old.', 'Failures appear during video meetings.', 'Firmware versions vary.'], answer: 'Validate ticket classification, normalize failures by model population, correlate workload, temperature, battery, firmware and age, reproduce on affected and healthy peers, propose containment and a controlled firmware pilot, and engage the vendor if evidence shows a model-level defect.' }
]

